## ES6 Class vs ES5 Function Constructor

```js
// ES5
function Person(name) {
  this.name = name;
}
Person.prototype.greet = function() {
  return 'Hi, I am ' + this.name;
};

// ES6
class Person {
  constructor(name) {
    this.name = name;
  }
  greet() {
    return `Hi, I am ${this.name}`;
  }
}
```

### Without `new`
```js
// ES5 — silently corrupts global scope
const p = Person('Alice'); // this === window/global
console.log(p); // undefined

// ES6 — throws immediately
const p = Person('Alice'); // TypeError: Class constructor must be called with new
```

### Extending Built-ins (ES6 only)
```js
class MyArray extends Array {
  sum() {
    return this.reduce((a, b) => a + b, 0);
  }
}
const arr = new MyArray(1, 2, 3);
console.log(arr.sum()); // 6
```

## Currying

### Basic Example
```js
// Non-curried
const add = (a, b) => a + b;
add(2, 3); // 5

// Curried
const curriedAdd = a => b => a + b;
const add5 = curriedAdd(5);
add5(3); // 8
add5(10); // 15
```

### Manual Curry Helper
```js
function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) {
      return fn.apply(this, args);
    }
    return function (...moreArgs) {
      return curried.apply(this, args.concat(moreArgs));
    };
  };
}

const multiply = curry((a, b, c) => a * b * c);
console.log(multiply(2)(3)(4)); // 24
console.log(multiply(2, 3)(4)); // 24
console.log(multiply(2)(3, 4)); // 24
```

### Practical Use Case
```js
const formatCurrency = currency => amount =>
  new Intl.NumberFormat('en-GB', { style: 'currency', currency }).format(amount);

const formatGBP = formatCurrency('GBP');
const formatUSD = formatCurrency('USD');

formatGBP(1500); // '£1,500.00'
formatUSD(1500); // '$1,500.00'
```

### Currying vs Partial Application
- **Currying**: always produces unary (single-argument) functions
- **Partial application**: fixes *some* arguments, result may take multiple arguments

## DOMContentLoaded vs window.load

```js
// Fires early — DOM is ready, resources may still be loading
document.addEventListener('DOMContentLoaded', () => {
  console.log('DOM ready');
  initApp(); // safe to query/manipulate DOM
});

// Fires late — everything including images loaded
window.addEventListener('load', () => {
  console.log('Page fully loaded');
  const img = document.querySelector('img');
  console.log(img.naturalWidth); // now safe to read
});
```

### Timeline
```
HTML parsing complete  →  DOMContentLoaded
Images/CSS/fonts done  →  window.load
```

### When to Use Which
| Use Case | Event |
|---|---|
| Initialise UI, attach listeners | `DOMContentLoaded` |
| Read image dimensions | `window.load` |
| Measure layout after fonts | `window.load` or `document.fonts.ready` |
| Performance timing | `PerformanceObserver` |

## AMD vs CommonJS vs ESM

### CommonJS (Node.js)
```js
// math.js
module.exports = {
  add: (a, b) => a + b,
};

// app.js
const { add } = require('./math');
console.log(add(2, 3)); // 5
```

### AMD (Browser, RequireJS)
```js
// math.js
define([], function () {
  return { add: (a, b) => a + b };
});

// app.js
require(['./math'], function (math) {
  console.log(math.add(2, 3)); // 5
});
```

### ES Modules (Modern Standard)
```js
// math.js
export const add = (a, b) => a + b;

// app.js
import { add } from './math.js';
console.log(add(2, 3)); // 5
```

### Comparison
| | CommonJS | AMD | ESM |
|---|---|---|---|
| Loading | Synchronous | Asynchronous | Asynchronous |
| Environment | Node.js | Browser | Both |
| Tree-shaking | No | No | Yes |
| Native browser support | No | Via RequireJS | Yes |

## Higher-Order Functions

### Takes a Function as Argument
```js
const numbers = [1, 2, 3, 4, 5];

// map, filter, reduce are all HOFs
const doubled = numbers.map(n => n * 2);       // [2, 4, 6, 8, 10]
const evens   = numbers.filter(n => n % 2 === 0); // [2, 4]
const sum     = numbers.reduce((acc, n) => acc + n, 0); // 15
```

### Returns a Function
```js
function multiplier(factor) {
  return (number) => number * factor;
}

const double = multiplier(2);
const triple = multiplier(3);

console.log(double(5)); // 10
console.log(triple(5)); // 15
```

### Practical: Function Composition
```js
const compose = (...fns) => x => fns.reduceRight((acc, fn) => fn(acc), x);

const trim     = s => s.trim();
const lowercase = s => s.toLowerCase();
const exclaim  = s => `${s}!`;

const process = compose(exclaim, lowercase, trim);
console.log(process('  Hello World  ')); // 'hello world!'
```

## Function.prototype.bind

### Basic Usage — Fixing `this`
```js
const user = {
  name: 'Alice',
  greet() {
    return `Hello, ${this.name}`;
  },
};

const greet = user.greet;
console.log(greet()); // 'Hello, undefined' — `this` is lost

const boundGreet = user.greet.bind(user);
console.log(boundGreet()); // 'Hello, Alice'
```

### Partial Application
```js
function multiply(a, b) {
  return a * b;
}

const double = multiply.bind(null, 2);
console.log(double(5));  // 10
console.log(double(10)); // 20
```

### Event Listener Cleanup
```js
class Counter {
  constructor() {
    this.count = 0;
    this.handleClick = this.increment.bind(this); // store reference
    document.addEventListener('click', this.handleClick);
  }
  increment() { this.count++; }
  destroy() {
    document.removeEventListener('click', this.handleClick);
  }
}
```

### bind vs call vs apply
| Method | Invokes immediately | Sets `this` | Pre-fills args |
|---|---|---|---|
| `call` | Yes | Yes | Yes (spread) |
| `apply` | Yes | Yes | Yes (array) |
| `bind` | No | Yes | Yes |

## ES5 vs ES6 Key Differences

### Variables
```js
// ES5
var x = 1; // function-scoped, hoisted

// ES6
let y = 1;   // block-scoped
const z = 2; // block-scoped, immutable binding
```

### Functions
```js
// ES5
var greet = function(name) { return 'Hi ' + name; };

// ES6
const greet = name => `Hi ${name}`; // arrow: lexical this
```

### Destructuring & Defaults
```js
// ES6
const { a = 10, b = 20 } = { a: 3 };
const [first, ...rest] = [1, 2, 3, 4];
```

### Classes & Modules
```js
// ES6 class
class Animal { constructor(name) { this.name = name; } }

// ES6 module
import { foo } from './foo.js';
export const bar = 42;
```

### Async
```js
// ES5: callbacks
fs.readFile(path, function(err, data) { ... });

// ES6: Promises
fetch(url).then(res => res.json()).then(data => ...);

// ES2017 (built on ES6 Promises)
async function loadData() {
  const data = await fetch(url).then(r => r.json());
}
```

## Avoiding Global Scope Pollution

### The Problem
```js
// lib-a.js
var config = { debug: false };

// lib-b.js (loaded later)
var config = { timeout: 3000 }; // silently overwrites lib-a's config!

// app.js
console.log(config.debug); // undefined — bug!
```

### Solutions
```js
// 1. IIFE (ES5 era)
(function () {
  var privateVar = 'only accessible here';
})();

// 2. ES Modules (modern)
// Each module has its own scope by default
export const config = { debug: false };

// 3. Namespace Object (legacy)
var MyApp = MyApp || {};
MyApp.config = { debug: false };
```

### The `window` Object
```js
// Any var declared at top-level becomes a window property
var foo = 'bar';
console.log(window.foo); // 'bar' — now accessible globally!

// let/const at top-level do NOT attach to window
let baz = 'qux';
console.log(window.baz); // undefined
```

## Binary Search

### Implementation (Iterative)
```js
function binarySearch(arr, target) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);

    if (arr[mid] === target) return mid;
    if (arr[mid] < target)  left = mid + 1;
    else                    right = mid - 1;
  }

  return -1;
}

const sorted = [1, 3, 5, 7, 9, 11, 13];
console.log(binarySearch(sorted, 7));  // 3
console.log(binarySearch(sorted, 6));  // -1
```

### Recursive Version
```js
function binarySearchRecursive(arr, target, left = 0, right = arr.length - 1) {
  if (left > right) return -1;
  const mid = Math.floor((left + right) / 2);
  if (arr[mid] === target) return mid;
  if (arr[mid] < target) return binarySearchRecursive(arr, target, mid + 1, right);
  return binarySearchRecursive(arr, target, left, mid - 1);
}
```

### Complexity
| | Time | Space |
|---|---|---|
| Iterative | O(log n) | O(1) |
| Recursive | O(log n) | O(log n) call stack |

### Visualisation for [1,3,5,7,9,11,13], target = 7
```
Step 1: mid = 6 → arr[6]=13 > 7 → right = 5
Step 2: mid = 2 → arr[2]=5  < 7 → left  = 3
Step 3: mid = 4 → arr[4]=9  > 7 → right = 3
Step 4: mid = 3 → arr[3]=7 === 7 → return 3
```
